        //  The cards are 140x190 in size

        //  Let's lay them out in a 8x2 grid, except we'll use a smaller cell size, so that
        //  the cards overlap horizontally

        Phaser.Actions.GridAlign(cards, {
            width: 8,
            height: 2,
            cellWidth: 80,
            cellHeight: 220,
            x: 50,
            y: 80
        });
    }
}

