                    duration: 2000,
                    x: dx,
                    y: dy,
                    scaleX: 1,
                    scaleY: 1,
                    angle: 360,
                    delay: i / 1500,
                    yoyo: true,
                    repeat: -1,
                    repeatDelay: 6

                });
