        this.load.image('logo', 'assets/sprites/phaser-large.png');
    }

    create ()
    {
        const gl = this.sys.game.renderer.gl;

        const consts = [
            gl.ZERO,
            gl.ONE,
            gl.SRC_COLOR,
            gl.ONE_MINUS_SRC_COLOR,
            gl.DST_COLOR,
            gl.ONE_MINUS_DST_COLOR,
            gl.SRC_ALPHA,
            gl.ONE_MINUS_SRC_ALPHA,
            gl.DST_ALPHA,
            gl.ONE_MINUS_DST_ALPHA,
            gl.CONSTANT_COLOR,
            gl.ONE_MINUS_CONSTANT_COLOR,
            gl.CONSTANT_ALPHA,
            gl.ONE_MINUS_CONSTANT_ALPHA,
            gl.SRC_ALPHA_SATURATE
        ];

        const equations = [
            gl.FUNC_ADD,
            gl.FUNC_SUBTRACT,
            gl.FUNC_REVERSE_SUBTRACT
        ];

        const list = [
            'ZERO',
            'ONE',
            'SRC_COLOR',
            'ONE_MINUS_SRC_COLOR',
            'DST_COLOR',
            'ONE_MINUS_DST_COLOR',
            'SRC_ALPHA',
            'ONE_MINUS_SRC_ALPHA',
            'DST_ALPHA',
            'ONE_MINUS_DST_ALPHA',
            'CONSTANT_COLOR',
            'ONE_MINUS_CONSTANT_COLOR',
            'CONSTANT_ALPHA',
            'ONE_MINUS_CONSTANT_ALPHA',
            'SRC_ALPHA_SATURATE'
        ];

        const list2 = [
            'FUNC_ADD',
            'FUNC_SUBTRACT',
            'FUNC_REVERSE_SUBTRACT'
        ];

        let srcRGBIndex = 1;
        let dstRGBIndex = 7;
        let srcAlphaIndex = 1;
        let dstAlphaIndex = 1;
        let equationIndex = 0;

        let srcRGB = consts[srcRGBIndex];
        let dstRGB = consts[dstRGBIndex];
        let srcAlpha = consts[srcAlphaIndex];
        let dstAlpha = consts[dstAlphaIndex];

        let newMode = [ srcRGB, dstRGB, srcAlpha, dstAlpha ];

        let equation = equations[equationIndex];

        let renderer = this.sys.game.renderer;

        let modeIndex = renderer.addBlendMode(newMode, equation);

        this.add.image(400, 300, 'turkey');

        this.add.rectangle(200, 300, 1, 600, 0xefefef);
