        g2Combine.setupAlphaTransfer(true, false, undefined, undefined, undefined, true);
        this.g2 = g2;
    }

    update (time, delta)
    {
        const d = 128 * Math.sin(time / 3000);
        this.g1.x = 640 + d;
        this.g2.x = 640 - d;
    }
}

