            fx.x = x / 512;
            fx.y = y / 512;

        });

        sprite.on('wheel', (pointer, x, y) => {

            fx.radius += y * -0.001;

            fx.radius = Phaser.Math.Clamp(fx.radius, 0, 1);

        });
    }
}

