        bunny.originY = 0;
    }

    update ()
    {
        largeText.y -= 0.3;
        bunny.x += vx;
        bunny.y += vy;

        if (bunny.x + bunny.width > 1024)
        {
            vx *= -1;
            bunny.x = 1024 - bunny.width;
        }
        else if (bunny.x < 0)
        {
            bunny.x = 0;
            vx *= -1;
        }
        if (bunny.y + bunny.height > 768)
        {
            vy *= -1;
            bunny.y = 768 - bunny.height;
        }
        else if (bunny.y < 0)
        {
            bunny.y = 0;
            vy *= -1;
        }
    }
