        blitter.createFromCallback(this.placeBob.bind(this), this.t * 7);
    }

    placeBob (bob)
    {
        if (this.i % 16 === 0)
        {
            this.x += 96;
            this.y = 0;
        }

        this.y += 32;

        bob.x = this.x + (Math.sin(this.y) * 16);
        bob.y = this.y;

        this.i++;
    }
}

