        this.numbers.push(this.add.image(32 + 5 * 50, 742, 'atlas', '0'));

        this.blitter = this.add.blitter(0, 0, 'atlas');

        for (let i = 0; i < 32; i++)
        {
            this.launch(i);
        }
        
        this.updateDigits();
    }

    update ()
    {
        if (this.input.activePointer.isDown)
        {
            for (let i = 0; i < 32; i++)
            {
                this.launch(i);
            }

            this.updateDigits();
        }
    }

    launch (i)
    {
        this.idx++;

        if (this.idx === 38)
        {
            this.idx = 1;
        }

        if (this.idx < 10)
        {
            this.frame = `veg0${this.idx.toString()}`;
        }
        else
        {
            this.frame = `veg${this.idx.toString()}`;
        }

        const bob = this.blitter.create(i * 32, 0, this.frame);

        this.tweens.add({
            targets: bob,
            duration: 2000,
            y: 650,
            delay: Math.random() * 2,
            ease: 'Sine.easeInOut',
            repeat: -1,
            yoyo: true
        });
    }

    updateDigits ()
