            yoyo: true,
            repeat: -1
        });

        this.tweens.add({
            targets: container,
            scale: 1.5,
            duration: 1000,
            ease: 'Sine.easeInOut',
            yoyo: true,
            repeat: -1
        });

        // Create a set of game objects and nest them inside several Containers.
