        this.tweens.add({ targets: lightsLayer.list, radius: 96, yoyo: true, duration: 1500, repeat: -1, ease: 'Sine.inOut' });

        gemsLayer.enableFilters().filters.external.add(new HueRotate.Controller(gemsLayer.filterCamera));
