        this.ropes.forEach((rope) => {

            let points = rope.points;

            for (let i = 0; i < points.length; i++)
            {
                points[i].y = Math.sin(i * 0.15 + this.count) * 24;
            }
    
            rope.setDirty();
    
        });
    }
