                setUniform('color1', [0, 0, 0, 0]);
                setUniform('color2', [0.8, 0.6, 0.2, 1]);
                setUniform('steps', 0);
                setUniform('repeat', 1);
                setUniform('offset', position);
            }
        }, 640, 360, 1024, 1024);

        gradient
            .setDisplaySize(1536, 1536)
            .setBlendMode(Phaser.BlendModes.ADD)
