class Example extends Phaser.Scene
{
    imageHeight = 0;
    imageWidth = 0;
    maxHeight = 120;
    spacing = 12;
    centerY = -200;
    centerX = 400;
    tileHeightHalf = 10;
    tileWidthHalf = 15;
    size = 24;
    gridHeight = 54;
    gridWidth = 54;
    cursors;
    py = 0;
    px = 0;
    land = [];
