        this.bar.scaleX = Math.sin(time / 200);

        this.cameras.main
        .setScroll(Math.cos(time / 1000) * 400, Math.sin(time / 1000) * 200)
        .setRotation(Math.sin(time / 500) * 0.1)
        .setZoom(1 + Math.sin(time / 2000) * 0.1);
