    initCamera ()
    {
        const worldWidth = this.scale.width * 2;
        const worldHeight = this.scale.height;

        this.cameras.main.setBounds(0, 0, worldWidth, worldHeight);
        this.physics.world.setBounds(0, -200, worldWidth, worldHeight + 200);
