            frameRate: 12,
            repeat: -1
        });

        this.anims.create({
            key: ANIMATION_KEYS.PLAYER_LEFT,
            frames: this.anims.generateFrameNumbers(SPRITE_KEYS.DUDE, { start: 0, end: 3 }),
