            this.points[i] = point;

            ++i;
            this.points[i] = point.clone().negate();

            ++i;
        }

        for (let j = 0; j < this.points.length; j++)
        {
            this.points[j].x += 400;
            this.points[j].y += 300;
        }

        this.graphics.strokePoints(this.points, false);
