            color.setGLTo(Phaser.Math.Hash(y), Phaser.Math.Hash(y + 1), Phaser.Math.Hash(y + 2));
            const r2 = this.add.rectangle(960, y, 384, 32, color.color);
            this.rects.push(r2);
