        {

            gameObject.x = dragX;
            gameObject.y = dragY;

            gameObject.getData('vector').set(dragX, dragY);

        });

        this.input.on('dragend', (pointer, gameObject) =>
        {

            gameObject.setFrame(0);

        });

        this.graphics = this.add.graphics();

    }

    update ()
