                data[i * cw * 4 + j * 4 + 0] = iteration * this.c1;
                data[i * cw * 4 + j * 4 + 1] = iteration * this.c2;
                data[i * cw * 4 + j * 4 + 2] = iteration * this.c3;
                data[i * cw * 4 + j * 4 + 3] = 255;
            }       
        }

        this.context.putImageData(imageData, 0, 0);
    }

