        }, this);

        this.events.on(Phaser.Scenes.Events.WAKE, function ()
        {
            this.wake(this.input, this.scene);
        }, this);
    }

    wake (input, scene)
    {
        input.once(Phaser.Input.Events.POINTER_DOWN, () =>
