            'bubble2',
            {
                atlas: 'testanims',
                frame: 'bubble',
                frameWidth: 34,
                frameHeight: 68
            });

        //  There is a new texture available called 'boom1', which we can assign to game objects:

        const config1 = {
            key: 'explode1',
            frames: this.anims.generateFrameNumbers('boom1', { start: 0, end: 23, first: 23 }),
