                    ], pointerTileX, pointerTileY);
                    break;
                default:
                    break;
            }
        }

    }

    getHelpMessage ()
    {
        return `Press 1/2/3 to change object to place.\nLeft click to place the tiles.\nSelected object: ${this.objectToPlace}`;
    }
}

